<script lang="ts">
  import {controlFlowCompilePlan,type ControlFlowMode} from '../../lib/curriculum';
  const modes:{id:ControlFlowMode;label:string;subtitle:string}[]=[
    {id:'eager',label:'Eager autograd',subtitle:'run Python, record the path'},
    {id:'python-flag',label:'Python flag',subtitle:'specialize and guard'},
    {id:'tensor-if',label:'Tensor if',subtitle:'break around the decision'},
    {id:'torch-cond',label:'torch.cond',subtitle:'capture structured branches'}
  ];
  let mode:ControlFlowMode='eager',shape=4,predicate=true,cacheKeys:string[]=[],status='not run yet',runs=0;
  $: plan=controlFlowCompilePlan(mode,+shape,predicate);
  $: code=mode==='eager'?`def loss_fn(x):\n    if x.sum() > 0:\n        y = torch.sin(x)\n    else:\n        y = torch.cos(x)\n    return y.square().mean()\n\nloss = loss_fn(x)\nloss.backward()`:
    mode==='python-flag'?`@torch.compile\ndef loss_fn(x, use_sin: bool):\n    if use_sin:\n        y = torch.sin(x)\n    else:\n        y = torch.cos(x)\n    return y.square().mean()`:
    mode==='tensor-if'?`@torch.compile\ndef loss_fn(x):\n    if x.sum() > 0:\n        y = torch.sin(x)\n    else:\n        y = torch.cos(x)\n    return y.square().mean()`:
    `def true_fn(x): return torch.sin(x)\ndef false_fn(x): return torch.cos(x)\n\n@torch.compile\ndef loss_fn(x):\n    pred = x.sum() > 0\n    y = torch.cond(pred, true_fn, false_fn, (x,))\n    return y.square().mean()`;
  function changeMode(next:ControlFlowMode){mode=next;cacheKeys=[];runs=0;status='not run yet'}
  function run(){runs+=1;if(plan.cacheKey===null){status=`Python chose ${plan.branch}; a fresh autograd graph recorded that path`;return}const hit=cacheKeys.includes(plan.cacheKey);if(hit){status=mode==='tensor-if'?'reused prefix and cached branch continuation':'guards passed → reused cached compiled region';return}if(mode==='tensor-if'){const sameShape=cacheKeys.some(key=>key.startsWith(`shape:${shape}|`));status=!cacheKeys.length?'captured prefix; Python chose a branch; captured its continuation':sameShape?'reused prefix; Python chose a new branch; captured that continuation':'shape guard failed → captured a new prefix and continuation'}else status=cacheKeys.length?'guard failed → captured and compiled another entry':'first call → captured and compiled';cacheKeys=[...cacheKeys,plan.cacheKey]}
  function reset(){cacheKeys=[];runs=0;status='not run yet'}
</script>

<section class="lab" aria-labelledby="compile-title">
  <header><div><span>Graph-generation lab</span><h3 id="compile-title">What does Python control flow become?</h3></div><button onclick={reset}>Reset compile cache</button></header>
  <nav aria-label="Choose execution model">{#each modes as item}<button class:active={mode===item.id} onclick={()=>changeMode(item.id)}><b>{item.label}</b><small>{item.subtitle}</small></button>{/each}</nav>
  <div class="workspace">
    <div class="code"><div class="filebar">control_flow.py <span>{mode==='eager'?'Python interpreter':'TorchDynamo + Python'}</span></div><pre><code>{code}</code></pre></div>
    <div class="execution">
      <div class="controls"><label>input values <button class:active={predicate} onclick={()=>predicate=true}>sum &gt; 0</button><button class:active={!predicate} onclick={()=>predicate=false}>sum ≤ 0</button></label><label>input shape <button class:active={shape===4} onclick={()=>shape=4}>[4]</button><button class:active={shape===8} onclick={()=>shape=8}>[8]</button></label><button class="run" onclick={run}>Run call {runs+1}</button></div>
      <div class="status"><small>latest call</small><b>{status}</b></div>
      {#if mode==='eager'}
        <div class="pipeline eager"><Block kind="python" title="Python executes if" detail={`${predicate?'true':'false'} branch`}/><Arrow/><Block kind="forward" title="runtime autograd graph" detail={predicate?'sum → sin → square → mean':'sum → cos → square → mean'}/><Arrow/><Block kind="backward" title="backward" detail="walk only recorded nodes"/></div>
      {:else if mode==='python-flag'}
        <div class="guard"><small>guard before reuse</small><code>{plan.guard}</code></div><div class="pipeline"><Block kind="dynamo" title="Dynamo bytecode trace" detail="flag becomes a specialization"/><Arrow/><Block kind="forward" title={`${plan.branch} FX graph`} detail={predicate?'sin → square → mean':'cos → square → mean'}/><Arrow/><Block kind="backward" title="AOTAutograd" detail="compiled backward region"/></div>
      {:else if mode==='tensor-if'}
        <div class="guard"><small>guard before reuse</small><code>{plan.guard}</code></div><div class="pipeline tensor"><Block kind="forward" title="FX region 1" detail="sum → greater-than"/><Arrow/><Block kind="break" title="GRAPH BREAK" detail="Python needs the tensor value"/><Arrow/><Block kind="python" title="Python chooses" detail={`${plan.branch} branch`}/><Arrow/><Block kind="forward" title="continuation FX" detail={predicate?'sin → square → mean':'cos → square → mean'}/></div><p class="backward-note">Backward still works, but the eager autograd engine crosses several compiled/eager regions instead of one optimizable graph.</p>
      {:else}
        <div class="guard"><small>guard before reuse</small><code>{plan.guard}</code></div><div class="cond-graph"><div class="cond-head"><b>one FX graph</b><span>cond predicate evaluated at runtime</span></div><div class="branches"><Block kind="forward" title="true subgraph" detail="sin → square → mean"/><Block kind="forward" title="false subgraph" detail="cos → square → mean"/></div><div class="selected">selected now: <b>{plan.branch}</b></div></div><p class="backward-note">Both branch functions are explicit graph regions, so changing the tensor predicate reuses the same structured graph when its guards still pass.</p>
      {/if}
      <div class="cache"><div><small>compiled cache entries</small><b>{plan.cacheKey===null?'none':cacheKeys.length}</b></div>{#if cacheKeys.length}{#each cacheKeys as key}<code>{key}</code>{/each}{:else}<span>{mode==='eager'?'eager mode does not reuse an FX cache':'run a call to create the first entry'}</span>{/if}</div>
    </div>
  </div>
  <footer><div><b>Autograd graph</b><span>records tensor operations from the path that ran</span></div><i>≠</i><div><b>FX compile graph</b><span>cached operations valid only while guards pass</span></div><i>≠</i><div><b>Python program</b><span>may contain work outside compiled regions</span></div></footer>
</section>

{#snippet Block(kind:string,title:string,detail:string)}<div class={`block ${kind}`}><small>{kind}</small><b>{title}</b><span>{detail}</span></div>{/snippet}
{#snippet Arrow()}<i class="arrow">→</i>{/snippet}

<style>
  .lab{margin:1.5rem 0;border:1px solid var(--border);border-radius:16px;background:var(--surface);overflow:hidden;box-shadow:0 16px 45px var(--shadow)}header{display:flex;align-items:center;justify-content:space-between;padding:1rem}header span{font:800 .58rem var(--font-mono);text-transform:uppercase;letter-spacing:.1em;color:var(--accent)}header h3{margin:.2rem 0}header>button{border:1px solid var(--border);background:var(--bg);color:var(--text);padding:.4rem .55rem;font-size:.57rem}nav{display:grid;grid-template-columns:repeat(4,1fr);border-block:1px solid var(--border)}nav button{border:0;border-right:1px solid var(--border);padding:.65rem .5rem;background:var(--bg);color:var(--text-muted);text-align:left}nav button:last-child{border:0}nav b,nav small{display:block}nav b{font-size:.62rem}nav small{margin-top:.15rem;font-size:.49rem}nav button.active{background:var(--accent);color:white}.workspace{display:grid;grid-template-columns:.82fr 1.35fr;min-height:520px;background:#111925;color:white}.code{border-right:1px solid #303b4c}.filebar{display:flex;justify-content:space-between;padding:.55rem .7rem;background:#1b2634;color:#a0adbd;font:.55rem var(--font-mono)}.filebar span{color:#748398}.code pre{box-sizing:border-box;min-height:450px;margin:0;padding:1rem;overflow:auto;color:#dce4ed;font:.59rem/1.65 var(--font-mono)}.execution{display:flex;flex-direction:column;padding:.8rem}.controls{display:grid;grid-template-columns:1fr .8fr auto;gap:.6rem;align-items:end}.controls label{display:flex;flex-wrap:wrap;gap:3px;color:#8e9caf;font-size:.51rem}.controls label>button{flex:1}.controls button{border:1px solid #3d4a5d;background:#182332;color:#bdc7d5;padding:.38rem;font-size:.52rem}.controls button.active{border-color:#df7656;color:#ff9b79}.controls .run{background:#df6540;border-color:#df6540;color:white;font-weight:750}.status{margin:.7rem 0;padding:.55rem .65rem;border:1px solid #354255;border-radius:5px;background:#192432}.status small,.status b{display:block}.status small{color:#79889b;font:.47rem var(--font-mono)}.status b{margin-top:.15rem;font-size:.56rem}.pipeline{display:flex;flex:1;align-items:center;justify-content:center;gap:.4rem}.pipeline.tensor{gap:.25rem}.block{flex:1;min-width:0;padding:.6rem;border:1px solid #3c485b;border-radius:6px;background:#192433}.block small,.block b,.block span{display:block}.block small{color:#7e8da0;font:.46rem var(--font-mono);text-transform:uppercase}.block b{margin:.2rem 0;font-size:.57rem}.block span{color:#97a4b5;font-size:.49rem;line-height:1.35}.block.forward{border-color:#687e9d}.block.backward{border-color:#a65f48}.block.break{border-color:#df6540;background:#32231f}.block.python{border-style:dashed}.arrow{color:#77879a;font-style:normal}.guard{display:flex;justify-content:space-between;gap:.5rem;padding:.45rem .55rem;border:1px solid #3a4759;border-radius:5px}.guard small{color:#7e8c9e;font-size:.47rem}.guard code{color:#ff9b79;font-size:.49rem}.backward-note{margin:.45rem 0;color:#8d9bad;font-size:.52rem}.cond-graph{display:flex;flex:1;flex-direction:column;justify-content:center;margin-top:.65rem;padding:.7rem;border:1px solid #566a88;border-radius:7px}.cond-head{display:flex;justify-content:space-between}.cond-head b{font:.62rem var(--font-mono)}.cond-head span{color:#8997a8;font-size:.48rem}.branches{display:grid;grid-template-columns:1fr 1fr;gap:.55rem;margin:.75rem 0}.selected{color:#8997a8;font-size:.52rem}.selected b{color:#ff9b79}.cache{display:flex;align-items:center;gap:.45rem;flex-wrap:wrap;padding-top:.6rem;border-top:1px solid #303b4b}.cache div{margin-right:auto}.cache small,.cache b{display:block}.cache small{color:#77869a;font-size:.46rem}.cache b{font:.72rem var(--font-mono)}.cache code{padding:.25rem .35rem;border-radius:3px;background:#1e2a39;color:#aab5c4;font-size:.45rem}.cache>span{color:#768598;font-size:.48rem}footer{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;align-items:center;gap:.7rem;padding:.75rem 1rem;background:var(--accent-soft)}footer div{display:flex;flex-direction:column}footer b{font:.62rem var(--font-mono)}footer span,footer i{color:var(--text-muted);font:normal .52rem var(--font-mono)}@media(max-width:760px){nav{grid-template-columns:1fr 1fr}.workspace{grid-template-columns:1fr}.code{border-right:0;border-bottom:1px solid #303b4c}.code pre{min-height:300px}.controls{grid-template-columns:1fr 1fr}.controls .run{grid-column:1/-1}.pipeline{min-height:180px;overflow:auto;justify-content:flex-start}.block{min-width:120px}footer{grid-template-columns:1fr;gap:.3rem}footer>i{display:none}}@media(max-width:450px){.controls{grid-template-columns:1fr}.branches{grid-template-columns:1fr}.pipeline.tensor .block{min-width:105px}}
</style>
